import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createRejectingProvider(rejection: unknown): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw rejection;
    },
    async generateStructured<T>(): Promise<T> {
      throw rejection;
    },
  };
}

// consume the async generator to trigger the orchestrator's try/catch
async function consume(gen: any): Promise<unknown> {
  try {
    // processMessage returns an AsyncGenerator, which is an AsyncIterable
    for await (const _ of gen) {
      // noop
    }
    return 'resolved without throwing';
  } catch (e) {
    return e;
  }
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('onError for non-Error rejections (acceptance)', () => {
  it('calls onError for a string rejection', async () => {
    // specs/hal-engine-config-hooks/spec.md#1
    const rejection = 'string boom';
    let reportedError: any;
    const hooks = {
      onError: async (_session: ChatSession, err: Error) => {
        reportedError = err;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider(rejection), promptBuilder, undefined, {hooks});

    const caught = await consume(orchestrator.processMessage(createSession('hi')));

    expect(caught).toBe(rejection);
    expect(reportedError).toBeInstanceOf(Error);
    expect(reportedError.cause).toBe(rejection);
  });

  it('calls onError for an object rejection', async () => {
    // specs/hal-engine-config-hooks/spec.md#2
    const rejection = {reason: 'object boom'};
    let reportedError: any;
    const hooks = {
      onError: async (_session: ChatSession, err: Error) => {
        reportedError = err;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider(rejection), promptBuilder, undefined, {hooks});

    const caught = await consume(orchestrator.processMessage(createSession('hi')));

    expect(caught).toBe(rejection);
    expect(reportedError).toBeInstanceOf(Error);
    expect(reportedError.cause).toBe(rejection);
  });

  it('calls onError for an undefined rejection', async () => {
    // specs/hal-engine-config-hooks/spec.md#3
    const rejection = undefined;
    let reportedError: any;
    const hooks = {
      onError: async (_session: ChatSession, err: Error) => {
        reportedError = err;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider(rejection), promptBuilder, undefined, {hooks});

    const caught = await consume(orchestrator.processMessage(createSession('hi')));

    expect(caught).toBe(rejection);
    expect(reportedError).toBeInstanceOf(Error);
    expect(reportedError.cause).toBe(rejection);
  });

  it('calls onError with original Error instance', async () => {
    // specs/hal-engine-config-hooks/spec.md#4
    const rejection = new Error('actual error');
    let reportedError: any;
    const hooks = {
      onError: async (_session: ChatSession, err: Error) => {
        reportedError = err;
      },
    };

    const orchestrator = createChatOrchestrator(createRejectingProvider(rejection), promptBuilder, undefined, {hooks});

    const caught = await consume(orchestrator.processMessage(createSession('hi')));

    expect(caught).toBe(rejection);
    expect(reportedError).toBe(rejection);
  });
});
